  var mc=MesaNueva();var cuenta=Crear(admin,mc.Id,"Concurrente");var pp=admin.AgregarProductoCuenta(Producto(admin,mc.Id,cuenta,1)).PedidoId;var r1=Producto(admin,mc.Id,cuenta,1);var r2=r1 with{OperacionId=Guid.NewGuid()};int exitos=0;Parallel.Invoke(()=>{try{admin.AgregarProductoCuenta(r1);Interlocked.Increment(ref exitos);}catch{}},()=>{try{Repo().AgregarProductoCuenta(r2);Interlocked.Increment(ref exitos);}catch{}});Ok(exitos==1&&admin.RevisarCuenta(pp).Total==20,"Versionado evita actualizaciones concurrentes obsoletas");
