 static void PruebasLecturaConcurrente()
 {
  var m=MesaNueva();var id=Crear(admin,m.Id,"Lecturas concurrentes");admin.AgregarProductoCuenta(Producto(admin,m.Id,id,1));
  Parallel.Invoke(()=>{for(var n=0;n<12;n++)Repo().ObtenerPedidoAbierto(m.Id);},()=>{for(var n=0;n<6;n++)admin.AgregarProductoCuenta(Producto(admin,m.Id,id,1));});
  Ok(admin.ConsultarServicioMesa(m.Id).Cuentas.Single().Original==70,"Refrescos y productos concurrentes respetan mesa antes de pedido sin interbloqueo");
  var carpeta=Path.Combine(Path.GetTempPath(),"SaboresPruebas","Operaciones");var guid=Guid.NewGuid();var archivo=Path.Combine(carpeta,admin.IdentificadorBase+"_"+admin.UsuarioActual!.Id+"_"+guid.ToString("N")+".bin");File.WriteAllBytes(archivo,[1,2,3]);
  try{var ilegible=DiarioOperaciones.Listar(admin).Single(x=>x.Id==guid);Ok(ilegible.Tipo=="Ilegible"&&DiarioOperaciones.ParaPedido(admin,m.Id,null).Any(x=>x.Id==guid),"Diario ilegible conserva bloqueo conservador sin adivinar alcance");try{DiarioOperaciones.Reanudar(admin,ilegible).GetAwaiter().GetResult();throw new Exception("No rechazó diario ilegible");}catch(Exception ex)when(ex is IOException or InvalidOperationException){}Ok(File.Exists(archivo),"Un diario ilegible no se elimina ni se reejecuta");}finally{Directory.CreateDirectory(Path.Combine(carpeta,"EvidenciasPrueba"));File.Move(archivo,Path.Combine(carpeta,"EvidenciasPrueba",Path.GetFileName(archivo)),false);}
 }
