 static T Campo<T>(Control f,string n)where T:Control=>(T)f.Controls.Find(n,true).Single();
 static void Mostrar(Form f){f.StartPosition=FormStartPosition.Manual;f.Location=new(0,0);f.Size=new(1500,1000);f.Show();SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());Application.DoEvents();}
 static void Esperar(Func<bool> c){var t=DateTime.UtcNow;while(!c()){if((DateTime.UtcNow-t).TotalSeconds>45){foreach(Form f in Application.OpenForms){Capturar(f,"timeout-"+f.GetType().Name);Console.WriteLine(f.GetType().Name+": "+string.Join(" | ",Descendientes(f).Where(c=>c.Name is "lblEstado" or "lblMensaje" or "cbCuentasServicio" or "btnCrearCuenta" or "btnAgregarProducto" or "lblResumen").Select(c=>$"{c.Name}: {c.Text}; visible={c.Visible}; enabled={c.Enabled}")));}throw new TimeoutException();}Application.DoEvents();Thread.Sleep(15);}Application.DoEvents();}
 static IEnumerable<Control> Descendientes(Control c){foreach(Control h in c.Controls){yield return h;foreach(var x in Descendientes(h))yield return x;}}
 static void Modal<T>(Action abrir,Action<T> completar)where T:Form{bool hecho=false;using var timer=new System.Windows.Forms.Timer{Interval=80};timer.Tick+=(_,_)=>{var f=Application.OpenForms.OfType<T>().FirstOrDefault();if(f is null||!f.Visible||hecho)return;hecho=true;try{completar(f);}catch(Exception ex){Console.Error.WriteLine(ex);Environment.Exit(1);}};timer.Start();abrir();Esperar(()=>hecho&&!Application.OpenForms.OfType<T>().Any());}
 static void Capturar(Form f,string nombre){Application.DoEvents();using var b=new Bitmap(f.Width,f.Height);f.DrawToBitmap(b,new(Point.Empty,b.Size));b.Save(Path.Combine(salida,nombre+".png"));Console.WriteLine($"CAPTURA {nombre} · DPI {f.DeviceDpi}");}
 static int Crear(RepositorioRestaurante repo,int mesa,string nombre,bool confirmado=true){var s=repo.ConsultarServicioMesa(mesa);return repo.GestionarCuentaMesa(new(Guid.NewGuid(),mesa,s.PedidoId,s.VersionPedido,0,null,"Crear",nombre,confirmado));}
 static SolicitudProductoCuenta Producto(RepositorioRestaurante repo,int mesa,int cuenta,int cantidad){var s=repo.ConsultarServicioMesa(mesa);var c=s.Cuentas.Single(x=>x.Id==cuenta);return new(Guid.NewGuid(),mesa,s.PedidoId,s.VersionPedido,cuenta,c.Version,producto,cantidad,null,null,null);}
 static SolicitudAbono Abono(RepositorioRestaurante repo,int pedido,int cuenta,decimal importe,string metodo="Efectivo",string estado="Confirmado"){var c=repo.ConsultarCobranza(pedido);var parte=c.Cuentas.Single(x=>x.Id==cuenta);var id=Guid.NewGuid();var datos=new SolicitudCobro(id,pedido,c.Pedido.Version,importe,true,"Público general",null,null,null,metodo,importe,estado,"Referencia de ensayo",null,true,true);return new(id,pedido,c.Pedido.Version,c.Pedido.Total,cuenta,parte.Saldo,importe,datos);}
 static Mesa MesaNueva(){admin.CrearMesa(++numero,4);return admin.ListarMesas().Single(x=>x.Numero==numero);}
 static string Estado(int mesa)=>admin.ListarMesas().Single(x=>x.Id==mesa).Estado;
 static RepositorioRestaurante Repo(string usuario="admin",string? clave=null){var r=new RepositorioRestaurante(new ConfiguracionConexionTemporal(cadena));if(r.IniciarSesion(usuario,clave??Clave)is null)throw new Exception("Sesión de fixture inválida.");return r;}
 static void Ok(bool b,string s){if(!b)throw new Exception("FALLO "+s);checks++;Console.WriteLine("OK "+s);}
 static void Deniega(Action a,string texto){try{a();}catch(Exception e)when(e is ArgumentException or InvalidOperationException or UnauthorizedAccessException or SqlException){Ok(true,texto);return;}throw new Exception("No rechazó: "+texto);}
 static string Escalar(string sql){using var c=new SqlConnection(cadena);c.Open();using var q=new SqlCommand(sql,c);return Convert.ToString(q.ExecuteScalar())!;}
 static int Numero(string sql)=>int.Parse(Escalar(sql));static void Sql(string sql)=>SqlEn(cadena,sql);static void SqlEn(string cs,string sql){using var c=new SqlConnection(cs);c.Open();using var q=new SqlCommand(sql,c){CommandTimeout=120};q.ExecuteNonQuery();}
